       if (!checkbox.checked) {
         checkbox.setCustomValidity('Please agree to the terms of use before submitting.');
         return;
       }

       event.preventDefault();
       checkbox.setCustomValidity('');
       status.textContent = 'Consent recorded successfully.';
     });
